import{packInfo,packOptions,assetSearchText}from'./asset-organizer.js';
import {terrainTile} from './smart-model.js';
import {OBJECT_GROUPS,TERRAIN_GROUPS,objectGroup,terrainGroup,matchesAsset,loadAssetPreferences,rememberAsset,toggleAssetFavorite,sortAssets} from './asset-browser.js';
import {RULES} from './world-model.js';
import {LEDGES} from './field-defs.js';

export const BRUSH_TOOLS=new Set(['terrain','texture','tree','wall','wallbox','room','ledge']);
export function toolPanel(tool,last='tiles'){
  if(['scenePlace','sceneArea','scenePath','sceneWarp','actorPlace'].includes(tool))return'events';
  if(BRUSH_TOOLS.has(tool))return'brushes';
  if(['stamp','building','interior','extract','door','gate'].includes(tool))return'objects';
  if(['brush','fill','rect','pick','erase'].includes(tool))return'tiles';
  if(['link','linkTarget','portal','doorTarget'].includes(tool))return'connections';
  if(['rules','rulesRect','rulesFill','inspect'].includes(tool))return'movement';
  if(['note','event','eventTarget','talk','nativeGift','field'].includes(tool))return'events';
  return last;
}
export function mapToolbox(api){
  const esc=api.esc,$=s=>document.querySelector(s);
  const prefs=loadAssetPreferences();
  const state={scope:'all',objectQuery:'',objectCategory:'all',objectPack:'all',objectGroup:'all',objectLimit:36,brushTab:'paths',brushQuery:'',brushGroup:'all',brushLimit:30,radius:1,lastBrush:'terrain',setId:'all'};
  const tabs=(items,current,attribute)=>`<div class="toolbox-tabs" role="tablist">${items.map(([id,label])=>`<button type="button" role="tab" aria-selected="${current===id}" ${attribute}="${id}" class="${current===id?'active':''}">${label}</button>`).join('')}</div>`;
  function thumb(p){const a=api.asset(p.assetId||p.a);if(!a)return'';return`<svg class="toolbox-thumb" viewBox="${p.sx||0} ${p.sy||0} ${p.sw||a.width} ${p.sh||a.height}" aria-hidden="true"><image href="${esc(a.data||a.src)}" width="${a.width}" height="${a.height}"/></svg>`;}
  const ready=t=>{state.lastBrush=BRUSH_TOOLS.has(t)?t:state.lastBrush;api.mode(t);api.collapse();};
  function objects(target){
    target.innerHTML=tabs([['all','Objects'],['native','ROM objects'],['furniture','Furniture'],['buildings','Buildings'],['interiors','Interiors'],['doors','Doors'],['mine','My library']],state.scope,'data-object-scope')+'<div id="objectBrowser"></div>';
    target.querySelectorAll('[data-object-scope]').forEach(b=>b.onclick=()=>{state.scope=b.dataset.objectScope;state.objectCategory='all';state.objectPack='all';state.objectGroup='all';state.setId='all';state.objectLimit=36;objects(target);});
    const body=$('#objectBrowser');
    if(state.scope==='native'){api.nativeObjects().render(body);return;}
    if(state.scope==='interiors'){api.interiors().render(body);return;}
    if(state.scope==='doors'){body.innerHTML='<p class="hint-line">Link existing tiles or place a doorway, then tap its arrival. Every portal remains movable.</p><div class="toolbox-actions"><button id="linkExistingTiles" type="button" class="primary">Link existing tiles</button><button id="doorArtwork" type="button">Choose doorway art</button><button id="gateArtwork" type="button">Opening gates</button></div>';$('#linkExistingTiles').onclick=()=>api.links().begin();$('#doorArtwork').onclick=()=>api.doors().open();$('#gateArtwork').onclick=()=>api.world().open('gates');return;}
    const prefabs=api.smart().prefabs(),sets=api.definitions().furnishingSets||[];
    let pool=prefabs.filter(p=>state.scope==='mine'?api.library().has('prefabs',p.id):state.scope==='buildings'?p.buildingTemplateId||p.category?.startsWith('Buildings'):state.scope==='furniture'?/interior|furnish|centre|center|mart|laborator|dojo|game corner|silph|department|kitchen|seating|table/i.test(p.category+' '+p.tags)&&!p.buildingTemplateId&&!p.category?.startsWith('Buildings'):true);
    const categories=[...new Set(pool.map(p=>p.category||'Other'))].sort();
    body.innerHTML=`${state.scope==='buildings'?'<div class="toolbox-actions"><button id="resizeBuildings" type="button">Resize a building</button><label class="check"><input id="offerBuildingInterior" type="checkbox"> Offer a linked interior</label></div>':''}<label>Asset pack<select id="objectPack" aria-label="Asset pack"><option value="all">All packs</option>${packOptions(pool,api.asset).map(pack=>`<option value="${esc(pack.id)}" ${state.objectPack===pack.id?'selected':''}>${esc(pack.name)} · ${pack.count}</option>`).join('')}</select></label><div class="toolbox-search"><input id="objectSearch" type="search" placeholder="Search objects…" aria-label="Search objects" value="${esc(state.objectQuery)}"><select id="objectCategory" aria-label="Object category"><option value="all">All categories / sets</option>${sets.map(set=>`<option value="set:${esc(set.id)}" ${set.id===state.setId?'selected':''}>Set · ${esc(set.name)}</option>`).join('')}${categories.map(c=>`<option value="${esc(c)}" ${c===state.objectCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="toolbox-result-line"><span id="objectResultCount"></span><button id="objectCreate" type="button">Create / import</button></div><div id="objectGroups" class="toolbox-tabs asset-group-tabs" role="group" aria-label="Object groups"></div><div id="toolboxObjects" class="toolbox-cards"></div><button id="moreObjects" type="button" class="full" hidden>Show more objects</button><details class="toolbox-details"><summary>Manage saved objects</summary><div class="toolbox-actions"><button id="manageObjects" type="button">Edit, duplicate & back up</button><button id="extractObject" type="button">Extract from map</button></div></details>`;
    if($('#resizeBuildings'))$('#resizeBuildings').onclick=()=>api.builder().open('expand');
    if($('#offerBuildingInterior')){$('#offerBuildingInterior').checked=api.builder().state.offerInterior;$('#offerBuildingInterior').onchange=e=>api.builder().state.offerInterior=e.target.checked;}
    function cards(){
      const q=state.objectQuery.trim().toLowerCase(),set=sets.find(s=>s.id===state.setId),chosen=api.selected();
      const groups=[['all','All'],['favorites','★ Favourites'],['recent','Recent'],...OBJECT_GROUPS.filter(g=>pool.some(p=>objectGroup(p)===g)).map(g=>[g,g])];$('#objectGroups').innerHTML=groups.map(([id,label])=>`<button type="button" data-object-group="${esc(id)}" class="${state.objectGroup===id?'active':''}" aria-pressed="${state.objectGroup===id}">${esc(label)}</button>`).join('');$('#objectGroups').querySelectorAll('[data-object-group]').forEach(button=>button.onclick=()=>{state.objectGroup=button.dataset.objectGroup;state.objectLimit=36;cards();});
      const found=sortAssets(pool.filter(p=>(state.objectCategory==='all'||p.category===state.objectCategory)&&(!set||set.prefabIds.includes(p.id))&&(state.objectPack==='all'||packInfo(p,api.asset).id===state.objectPack)&&q.split(/\s+/).filter(Boolean).every(word=>assetSearchText(p,api.asset).includes(word))&&(state.objectGroup==='all'||state.objectGroup==='favorites'&&prefs.favorites.includes('p:'+p.id)||state.objectGroup==='recent'&&prefs.recent.includes('p:'+p.id)||objectGroup(p)===state.objectGroup)),prefs,'p:');
      $('#objectResultCount').textContent=found.length+' objects';
      $('#toolboxObjects').innerHTML=found.slice(0,state.objectLimit).map(p=>`<article class="toolbox-card asset-choice ${chosen?.id===p.id?'active':''}"><button type="button" class="asset-place" data-object-id="${esc(p.id)}" aria-label="Place ${esc(p.name)}">${thumb(p)}<b>${esc(p.name)}</b><small>${esc(objectGroup(p))} · ${p.w} × ${p.h} tiles</small><small>${esc(packInfo(p,api.asset).name)}</small></button><button type="button" class="asset-pieces" data-object-pieces="${esc(p.id)}">Tiles / pieces</button><button type="button" class="asset-star" data-star-object="${esc(p.id)}" aria-label="Favourite ${esc(p.name)}" aria-pressed="${prefs.favorites.includes('p:'+p.id)}">${prefs.favorites.includes('p:'+p.id)?'★':'☆'}</button></article>`).join('')||'<p class="empty">No matching objects. Try another group or search.</p>';
      target.querySelectorAll('[data-star-object]').forEach(button=>button.onclick=()=>{toggleAssetFavorite(prefs,'p:'+button.dataset.starObject);cards();});
      $('#moreObjects').hidden=found.length<=state.objectLimit;
      target.querySelectorAll('[data-object-pieces]').forEach(b=>b.onclick=()=>api.pieces(prefabs.find(p=>p.id===b.dataset.objectPieces)).catch(e=>api.toast(e.message)));
      target.querySelectorAll('[data-object-id]').forEach(b=>b.onclick=()=>{const p=prefabs.find(v=>v.id===b.dataset.objectId);rememberAsset(prefs,'p:'+p.id);api.choosePrefab(p);api.collapse();});
    }
    $('#objectPack').onchange=e=>{state.objectPack=e.target.value;state.objectCategory='all';state.objectGroup='all';state.setId='all';$('#objectCategory').value='all';state.objectLimit=36;cards();};
    $('#objectSearch').oninput=e=>{state.objectQuery=e.target.value;state.objectLimit=36;cards();};$('#objectCategory').onchange=e=>{state.setId=e.target.value.startsWith('set:')?e.target.value.slice(4):'all';state.objectCategory=state.setId==='all'?e.target.value:'all';state.objectLimit=36;cards();};$('#moreObjects').onclick=()=>{state.objectLimit+=36;cards();};
    $('#objectCreate').onclick=api.importArtwork;$('#manageObjects').onclick=()=>api.smart().open('objects');$('#extractObject').onclick=()=>{api.smart().state.extractStart=null;ready('extract');};cards();
  }
  function brushTabFor(tool){return{terrain:'paths',texture:'textures',tree:'trees',wall:'walls',wallbox:'walls',room:'rooms',ledge:'ledges'}[tool];}
  function follow(tool){const tab=brushTabFor(tool);if(tab){state.brushTab=tab;state.lastBrush=tool;}if(tool==='stamp'&&['interiors','doors'].includes(state.scope))state.scope='all';if(tool==='building')state.scope='buildings';if(tool==='interior')state.scope='interiors';if(tool==='door'||tool==='gate')state.scope='doors';}
  function brushes(target){
    target.innerHTML=tabs([['paths','Paths'],['textures','Textures'],['trees','Trees'],['walls','Walls'],['rooms','Rooms'],['ledges','Ledges']],state.brushTab,'data-brush-tab')+'<div id="brushBrowser"></div>';
    target.querySelectorAll('[data-brush-tab]').forEach(b=>b.onclick=()=>{state.brushTab=b.dataset.brushTab;state.brushQuery='';state.brushGroup='all';state.brushLimit=30;brushes(target);});
    const body=$('#brushBrowser'),smart=api.smart(),builder=api.builder(),world=api.world();
    if(state.brushTab==='trees'){
      if(!builder.state.treeIds.length&&builder.trees()[0])builder.state.treeIds=[builder.trees()[0].id];
      body.innerHTML=`<div class="field-row"><label>Brush size<select id="treeBrushRadius">${[1,2,3,4].map(n=>`<option value="${n}" ${builder.state.radius===n?'selected':''}>${n===1?'Single trunk':n+' tile radius'}</option>`).join('')}</select></label><label>Trunk spacing<select id="treeBrushSpacing">${[1,2,3,4].map(n=>`<option value="${n}" ${builder.state.spacing===n?'selected':''}>${n} tiles</option>`).join('')}</select></label></div><div class="toolbox-actions"><button id="useTreeBrush" type="button" class="primary">Paint trees</button><button id="eraseTreeBrush" type="button">Erase brush trees</button></div><p class="hint-line">Select several trees to mix them. Trunks stay solid; leaves overlap.</p><div class="toolbox-cards">${builder.trees().map(p=>`<label class="toolbox-card tree-option ${builder.state.treeIds.includes(p.id)?'active':''}">${thumb(p)}<span><input data-tree-choice="${esc(p.id)}" type="checkbox" ${builder.state.treeIds.includes(p.id)?'checked':''}> ${esc(p.name)}</span></label>`).join('')}</div>`;
      $('#treeBrushRadius').onchange=e=>builder.state.radius=+e.target.value;$('#treeBrushSpacing').onchange=e=>builder.state.spacing=+e.target.value;body.querySelectorAll('[data-tree-choice]').forEach(b=>b.onchange=()=>{builder.state.treeIds=[...body.querySelectorAll('[data-tree-choice]:checked')].map(b=>b.dataset.treeChoice);b.closest('label').classList.toggle('active',b.checked);});
      const start=erase=>{if(!erase&&!builder.state.treeIds.length){api.toast('Choose at least one tree.');return;}builder.state.erase=erase;api.attach('prefabs',builder.trees().filter(p=>builder.state.treeIds.includes(p.id)));ready('tree');};$('#useTreeBrush').onclick=()=>start(false);$('#eraseTreeBrush').onclick=()=>start(true);return;
    }
    if(state.brushTab==='ledges'){
      const f=api.field();body.innerHTML=`<p class="hint-line">Paint the edge the player jumps over. The landing tile must be clear.</p><div class="rule-presets">${Object.entries(LEDGES).map(([id,d])=>`<button data-jump-direction="${id}" class="${f.state.direction===id?'active':''}" type="button">${{south:'↓',north:'↑',east:'→',west:'←'}[id]} ${d.name}</button>`).join('')}</div><div class="toolbox-actions"><button id="useLedgeBrush" type="button" class="primary">Paint jump ledges</button><button id="eraseLedgeBrush" type="button">Erase jump rules</button><button id="ledgeArtOptions" type="button">Ledge artwork / HM tools</button></div>`;
      body.querySelectorAll('[data-jump-direction]').forEach(b=>b.onclick=()=>{f.state.direction=b.dataset.jumpDirection;body.querySelectorAll('[data-jump-direction]').forEach(v=>v.classList.toggle('active',v===b));});$('#useLedgeBrush').onclick=()=>{f.state.erase=false;ready('ledge');};$('#eraseLedgeBrush').onclick=()=>{f.state.erase=true;ready('ledge');};$('#ledgeArtOptions').onclick=()=>f.open('ledges');return;
    }
    if(state.brushTab==='walls'){
      body.innerHTML=`<div class="toolbox-actions"><button id="eraseWallBrush" type="button">Erase walls</button><button id="customWallBrush" type="button">Custom walls & gates</button></div><div class="toolbox-cards">${world.walls().map(w=>`<article class="toolbox-card">${w.preview?`<img class="toolbox-thumb" loading="lazy" src="${esc(w.preview)}" alt="">`:thumb(w)}<b>${esc(w.name)}</b><div class="toolbox-actions"><button type="button" data-use-wall="${esc(w.id)}">Draw</button>${w.perimeter?`<button type="button" data-use-enclosure="${esc(w.id)}">Enclose</button>`:''}</div></article>`).join('')}</div>`;
      const use=(id,box)=>{const w=world.walls().find(w=>w.id===id);api.attach('wallStyles',[w]);world.state.wallId=id;world.state.erase=false;world.state.shape=box?'box':'line';ready(box?'wallbox':'wall');};body.querySelectorAll('[data-use-wall]').forEach(b=>b.onclick=()=>use(b.dataset.useWall,false));body.querySelectorAll('[data-use-enclosure]').forEach(b=>b.onclick=()=>use(b.dataset.useEnclosure,true));$('#eraseWallBrush').onclick=()=>{world.state.erase=true;ready('wall');};$('#customWallBrush').onclick=()=>world.open('walls');return;
    }
    if(state.brushTab==='rooms'){
      body.innerHTML=`<p class="hint-line">Draw a room with repeating floor and fitted wallpaper. For a complete furnished layout, choose Objects → Interiors.</p><div class="toolbox-cards">${smart.rooms().map(r=>`<button class="toolbox-card ${smart.state.roomId===r.id?'active':''}" type="button" data-room-brush="${esc(r.id)}">${thumb({...r.wall,sw:Math.min(3,r.wall.cols||3)*(r.wall.size||16),sh:(r.wall.rows||3)*(r.wall.size||16)})}<b>${esc(r.name)}</b></button>`).join('')}</div><button id="customRoomStyle" type="button">Custom wallpaper & room styles</button>`;
      body.querySelectorAll('[data-room-brush]').forEach(b=>b.onclick=()=>{smart.state.roomId=b.dataset.roomBrush;ready('room');});$('#customRoomStyle').onclick=()=>smart.open('rooms');return;
    }
    const texture=state.brushTab==='textures';
    body.innerHTML=`<button id="matchRomTerrain" type="button" class="full">Make brushes matching this ROM map</button><p class="hint-line">Uses your map’s own colours for paths, paving and grass. Generated brushes appear below. Bundled brushes may use other palettes.</p><div class="field-row"><label>Find ${texture?'textures':'paths'}<input id="brushSearch" type="search" placeholder="City, route, grass, water…" value="${esc(state.brushQuery)}"></label><label>Brush size<select id="brushRadius">${[1,2,3,4].map(n=>`<option value="${n}" ${state.radius===n?'selected':''}>${n===1?'1 tile':(n*2-1)+' tiles'}</option>`).join('')}</select></label></div><p class="hint-line">${texture?'Paint a repeating surface. Choose Paint for individual source tiles.':'Draw paths and contours; edges and inside corners fit automatically.'}</p><label>Terrain group<select id="terrainGroup"><option value="all">All terrain</option>${TERRAIN_GROUPS.map(g=>`<option value="${esc(g)}" ${state.brushGroup===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label><div id="brushCards" class="toolbox-cards"></div><button id="moreBrushes" type="button" class="full" hidden>Show more brushes</button><button id="customTerrainBrush" type="button">Make / manage custom terrain</button>`;
    $('#matchRomTerrain').onclick=async()=>{try{const ids=await api.romTerrain();state.brushQuery='';state.brushGroup='all';state.brushLimit=30;brushes(target);api.toast(ids.length+' matching ROM brushes added. Choose one to paint.');}catch(e){api.toast(e.message);}};
    const cards=()=>{const q=state.brushQuery.toLowerCase(),all=sortAssets(smart.terrains().filter(t=>matchesAsset({...t,tags:[...(t.tags||[]),...(t.locations||[])]},q)&&(state.brushGroup==='all'||terrainGroup(t)===state.brushGroup)),prefs,'t:').sort((a,b)=>Number(b.category?.startsWith('Current ROM'))-Number(a.category?.startsWith('Current ROM')));$('#brushCards').innerHTML=all.slice(0,state.brushLimit).map(t=>{const tile=terrainTile(t,255);return`<button type="button" class="toolbox-card ${smart.state.terrainId===t.id?'active':''}" data-brush-style="${esc(t.id)}">${!texture&&t.preview?`<img class="toolbox-thumb" loading="lazy" src="${esc(t.preview)}" alt="">`:thumb({...tile,sw:16,sh:16})}<b>${esc(t.name)}</b><small>${esc(t.category)}</small></button>`;}).join('')||'<p class="empty">No matching brushes.</p>';$('#moreBrushes').hidden=all.length<=state.brushLimit;body.querySelectorAll('[data-brush-style]').forEach(b=>b.onclick=()=>{const t=smart.terrains().find(t=>t.id===b.dataset.brushStyle);rememberAsset(prefs,'t:'+t.id);smart.state.terrainId=t.id;smart.state.erase=false;if(texture){const tile=terrainTile(t,255);api.setBrush({assetId:tile.a,sx:tile.sx,sy:tile.sy,cols:1,rows:1,tileSize:16,movementMode:tile.movementMode,movementBehavior:tile.movementBehavior});}api.attach('terrainSets',[t]);ready(texture?'texture':'terrain');});};
    $('#terrainGroup').onchange=e=>{state.brushGroup=e.target.value;state.brushLimit=30;cards();};
    $('#brushSearch').oninput=e=>{state.brushQuery=e.target.value;state.brushLimit=30;cards();};$('#brushRadius').onchange=e=>state.radius=+e.target.value;$('#moreBrushes').onclick=()=>{state.brushLimit+=30;cards();};$('#customTerrainBrush').onclick=()=>smart.open('terrain');cards();
  }
  function movement(target){
    api.world().movementPanel(target,api.collapse);
  }
  function events(target){
    target.innerHTML=`<div class="toolbox-actions"><button id="newVisualScene" type="button" class="primary">Visual scenes</button><button id="newMapEvent" type="button">＋ Basic event</button><button id="eventManager" type="button">Manage / recipes</button><button id="hmMapTools" type="button">HM objects & Flash</button></div><p class="hint-line">Tap a tile to add dialogue, a step trigger or an action sequence.</p>${api.map().markers.filter(n=>n.runtime||n.creatureGift).map(n=>`<button class="connection-item" data-map-event="${esc(n.id)}" type="button"><b>${esc(n.title||'Event')}</b><span>${n.x}, ${n.y} · ${esc(n.runtime?.trigger||'Interaction')}</span></button>`).join('')}`;
    $('#newVisualScene').onclick=()=>api.scenes().open();$('#newMapEvent').onclick=()=>ready('event');$('#eventManager').onclick=()=>api.events().open();$('#hmMapTools').onclick=()=>api.field().open();target.querySelectorAll('[data-map-event]').forEach(b=>b.onclick=()=>api.editEvent(api.map().markers.find(n=>n.id===b.dataset.mapEvent)));
  }
  function tools(target){
    const actions=[['native','ROM objects & map check','stamp'],['town','Create town · FireRed','maps'],['event','Events & dialogue','note'],['rules','Walking rules','brush'],['link','Link maps / portals','link'],['doors','Doors & gates','link'],['crop','Crop / resize map','rect'],['buildings','Buildings & interiors','stamp'],['wall','Walls & fences','layers'],['fill','Fill area','fill'],['rect','Paint rectangle','rect'],['erase','Erase layer','erase'],['pick','Pick a tile','pick'],['note','Planning pin','note'],['reference','Trace screenshot','image'],['play','Quick play check','move']];
    target.innerHTML='<p class="hint-line">Map editing tools. Sprite, Pokémon and game data editors live in Workshop.</p><button id="customiseToolbar" type="button" class="full">Customise toolbar · pin and reorder</button><div class="map-tool-grid">'+actions.map(([id,label,icon])=>`<button data-map-action="${id}" type="button">${api.icon(icon)}<span>${label}</span></button>`).join('')+'</div>';$('#customiseToolbar').onclick=api.customiseToolbar;
    target.querySelectorAll('[data-map-action]').forEach(b=>b.onclick=()=>{const id=b.dataset.mapAction;if(id==='native'){state.scope='native';api.panel('objects');}else if(id==='town'){api.nativeObjects().town().catch(e=>api.toast(e.message));}else if(id==='doors'){state.scope='doors';api.panel('objects');}else if(id==='buildings'){state.scope='buildings';api.panel('objects');}else if(id==='wall'){state.brushTab='walls';api.panel('brushes');}else if(id==='reference')api.reference();else if(id==='crop')api.crop().begin();else if(id==='link')api.links().begin();else if(id==='rules'){api.mode('rules');api.panel('movement');}else if(id==='event'){api.mode('event');api.panel('events');}else if(id==='play'){api.collapse();api.world().startPlay();}else ready(id);});
  }
  return{state,follow,objects,brushes,movement,events,tools,defaultBrush(){const tool=state.lastBrush;if(tool==='tree'&&!api.builder().state.treeIds.length)api.builder().state.treeIds=[api.builder().trees()[0]?.id].filter(Boolean);api.mode(tool);}};
}
